HERE=Path(__file__).resolve().parent;RUN=HERE.parent;ROOT=RUN.parents[4]
def bind(p):return {'path':p.relative_to(ROOT).as_posix(),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
